import CleanCSS from 'clean-css' // 压缩css
import { writeFileSync } from 'fs' // 写文件
import copyfiles from './rollup-plug-copyfile/rollup-plug-copyfile'
    // ...
export default {
  input: 'src/index.js',
  plugins: [
    babel(),
    json(),
    resolve({ extensions: ['.vue'] }),
    commonjs(),
    css({ output(style) {
      // 压缩 css 写入 dist/vue-rollup-component-template.css
      writeFileSync('dist/popup.css', new CleanCSS().minify(style).styles)
    } }),
    // css: false 将<style>块转换为导入语句，rollup-plugin-css-only可以提取.vue文件中的样式
    vue({ css: false }),
    copyfiles([
      {
        from:'src/iconfont',
        to:'dist'
      }
    ])
  ]
}

